struct Expr;
struct Const { double v; };
struct Add { std::unique_ptr<Expr> l, r; };
struct Expr { std::variant<Const, Add, Get, Log> node; };

double eval(const Expr& e) {
    return std::visit(overloaded{
        [](const Const& c) { return c.v; },
        [&](const Add& a) { return eval(*a.l) + eval(*a.r); },
        [&](const Get& g) { return env.read(g.key); },
        [&](const Log& l) { env.log(l.msg); return 0.0; }}, e.node);
}

